const source = $('Ler pendencias e configuracao ativa').item.json;
if (source.provedor !== 'openrouter') throw new Error(`Unsupported AI provider: ${source.provedor}`);
const content = $json.choices?.[0]?.message?.content;
if (typeof content !== 'string') throw new Error('OpenRouter returned no structured content');
const parsed = JSON.parse(content.replace(/^```(?:json)?\s*|\s*```$/g, ''));
return { json: { atendimento_id: source.atendimento_id, prompt_id: source.prompt_id, prompt_versao: source.prompt_versao, checklist: parsed.checklist, falhas_identificadas: parsed.falhas_identificadas, resumo_atendimento: parsed.resumo_atendimento } };
